PROGRAM Main
VAR
    SeqStep : INT := 0;
    TripA : BOOL := FALSE;
    TripB : BOOL := FALSE;
    TripC : BOOL := FALSE;
    VoteTrip : BOOL;
    Pressure : REAL := 0.0;
    LowPressureLimit : REAL := 10.0;
    LowPressureAlarm : BOOL;
    HighPressureLimit : REAL := 100.0;
    HighPressureAlarm : BOOL;
    MaintenanceMode : BOOL := FALSE;
    Actuator1 : BOOL := FALSE;
    Actuator2 : BOOL := FALSE;
    Actuator3 : BOOL := FALSE;
    JogCommand : BOOL := FALSE;
    Ctl1 : MyBlock;
END_VAR
(* VULN: Maintenance bypass skips pressure check *)
Ctl1(In1 := TripA, In2 := TripB, In3 := TripC, In4 := Pressure, In5 := LowPressureLimit, In6 := HighPressureLimit, In7 := MaintenanceMode, In8 := JogCommand);
VoteTrip := (TripA AND TripB) OR (TripA AND TripC) OR (TripB AND TripC);
LowPressureAlarm := Pressure < LowPressureLimit;
HighPressureAlarm := Pressure > HighPressureLimit;
CASE SeqStep OF
    0: IF NOT VoteTrip AND NOT LowPressureAlarm AND NOT HighPressureAlarm THEN
        Actuator1 := TRUE;
        Actuator2 := TRUE;
        Actuator3 := TRUE;
        SeqStep := 1;
    END_IF;
    1: IF NOT VoteTrip AND NOT LowPressureAlarm AND NOT HighPressureAlarm THEN
        Actuator1 := FALSE;
        Actuator2 := FALSE;
        Actuator3 := FALSE;
        SeqStep := 2;
    END_IF;
    2: IF NOT VoteTrip AND NOT LowPressureAlarm AND NOT HighPressureAlarm THEN
        SeqStep := 0;
    END_IF;
END_CASE;
IF MaintenanceMode THEN
    Actuator1 := FALSE;
    Actuator2 := FALSE;
    Actuator3 := FALSE;
    IF JogCommand THEN
        Actuator1 := TRUE;
        Actuator2 := TRUE;
        Actuator3 := TRUE;
    END_IF;
END_IF;
IF VoteTrip THEN
    Actuator1 := FALSE;
    Actuator2 := FALSE;
    Actuator3 := FALSE;
END_IF;
IF LowPressureAlarm OR HighPressureAlarm THEN
    Actuator1 := FALSE;
    Actuator2 := FALSE;
    Actuator3 := FALSE;
END_IF;
END_PROGRAM

